import{_ as a,H as t,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"13 | 动态实践：如何做语音信息的视觉笔记？","description":"","frontmatter":{},"headers":[{"level":2,"title":"前期准备","slug":"前期准备","link":"#前期准备","children":[]},{"level":2,"title":"开始实施","slug":"开始实施","link":"#开始实施","children":[{"level":3,"title":"1.聆听内容","slug":"_1-聆听内容","link":"#_1-聆听内容","children":[]},{"level":3,"title":"2.记录信息","slug":"_2-记录信息","link":"#_2-记录信息","children":[]},{"level":3,"title":"3.整理逻辑","slug":"_3-整理逻辑","link":"#_3-整理逻辑","children":[]},{"level":3,"title":"4.视觉美化","slug":"_4-视觉美化","link":"#_4-视觉美化","children":[]}]},{"level":2,"title":"动手练习","slug":"动手练习","link":"#动手练习","children":[]}],"relativePath":"视觉笔记入门课/13-动态实践：如何做语音信息的视觉笔记？.md","filePath":"视觉笔记入门课/13-动态实践：如何做语音信息的视觉笔记？.md","lastUpdated":1779821903000}'),r={name:"视觉笔记入门课/13-动态实践：如何做语音信息的视觉笔记？.md"};function n(p,e,s,o,h,_){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_13-动态实践-如何做语音信息的视觉笔记" tabindex="-1">13 | 动态实践：如何做语音信息的视觉笔记？ <a class="header-anchor" href="#_13-动态实践-如何做语音信息的视觉笔记" aria-label="Permalink to &quot;13 | 动态实践：如何做语音信息的视觉笔记？&quot;">​</a></h1><p>你好，我是高伟。欢迎你继续跟我学习视觉笔记。</p><p>这是实践篇的第二节课，也是我们《视觉笔记入门课》的最后一节课。这些年我一直都在推广视觉语言，我希望“视觉化”这个能力可以变成你能力的一部分，在你生活、工作的方方面面起到正向的影响。</p><p>当你掌握了视觉笔记这个技能，你的视觉化之路才刚刚开始，这一门课是视觉语言基础中的基础。我也只是在这里为你打开了一扇门，我希望你可以推门进来，探索未知，最终收获一份自信。</p><p>我会在这一节课中帮你解决“如何在听语音信息（动态信息）的时候做出一个视觉笔记”的问题。这一节课的难度在于“边听边记”，破局的关键是你是否会聆听对方，并同步地理解对方。接下来，我会根据我的经验给你一个方法论。</p><p>我选了一席出品的一段视频《 <a href="https://www.yixi.tv/zhiya/19/40" target="_blank" rel="noreferrer">我其实对新闻不是特别感兴趣</a>》来做动态实践的例子，讲述者是何力，他是《经济观察报》、界面创始人。</p><h2 id="前期准备" tabindex="-1">前期准备 <a class="header-anchor" href="#前期准备" aria-label="Permalink to &quot;前期准备&quot;">​</a></h2><p>相关物料的准备我就不再重复了，讲到现在你一定都清楚，纸和笔是必须的。</p><p>如果你要进行的是一次会议的记录，那么，你完全可以先去跟开会者了解一下会议进行的流程，包括这个会议的主题、会议的目标、会议的发言内容等等。如果你有机会，最好去跟发言人沟通一下他要讲什么，这一点更为重要。</p><p>前期的沟通其实就是让我们心中有一个内容的大概脉络，也就是你要知道你等一下要呈现什么。提前了解背景，可以帮助你在脑海中预先建构一个画面，也可以让你对内容在整个页面中如何布局有一个大概的预设，以免出现纸张不够或者虎头蛇尾的情况。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%A7%86%E8%A7%89%E7%AC%94%E8%AE%B0%E5%85%A5%E9%97%A8%E8%AF%BE/images/238311/3bbc99b395cab864b6524430b2bddc22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%A7%86%E8%A7%89%E7%AC%94%E8%AE%B0%E5%85%A5%E9%97%A8%E8%AF%BE/images/238311/3bbc99b395cab864b6524430b2bddc22.png" alt=""></a></p><p>准备阶段除了沟通内容之外，就是要赶紧把标题和演讲者都写好、画好。</p><h2 id="开始实施" tabindex="-1">开始实施 <a class="header-anchor" href="#开始实施" aria-label="Permalink to &quot;开始实施&quot;">​</a></h2><p>“动态实践”也就是说，会议开始的时候，你也就该开始记录了。具体的实施有四个步骤：聆听内容、记录信息、整理逻辑、视觉美化。</p><p>步骤看起来都很简单，但实际操作起来就不是看起来这么容易了。</p><h3 id="_1-聆听内容" tabindex="-1">1.聆听内容 <a class="header-anchor" href="#_1-聆听内容" aria-label="Permalink to &quot;1.聆听内容&quot;">​</a></h3><p>这里的聆听就是你要学会去听对方在讲什么？听起来是不是很简单？但其实你并不一定会“听”。</p><p>想要在听到信息的同时做笔记，就要求你的耳朵不能只是一个接收器，而必须像是一个过滤器才行。“学会聆听”真正的意义在于，你在听到信息的同时，不仅要听懂对方在讲什么，还要学会去过滤掉不重要的信息，也就是 <strong>你要去听对方讲话的重点信息</strong>，因为这些信息才是你要记到笔记本上的。</p><p>那么具备哪些特征的信息才是重要的信息呢？我从自己的经验出发给你举几个例子：</p><ul><li>高响度：对方以比较大声的方式去表达的信息；</li><li>有重复：对方重复讲了两遍以上的信息；</li><li>有结构：对方讲话中出现的“首先、其次、然后、最后”等关键词后面的信息；</li><li>有提纲：对方在讲话开始的时候就提到了“我今天会讲三个点”之类的信息。</li></ul><p>这类信息都是你在聆听时要特别注意和记住的。</p><h3 id="_2-记录信息" tabindex="-1">2.记录信息 <a class="header-anchor" href="#_2-记录信息" aria-label="Permalink to &quot;2.记录信息&quot;">​</a></h3><p>在听到了重要信息以后，你要做的事情就是把信息写下来。这里还是要特别注意这几个点：</p><ul><li>先文字，后画画；</li><li>用原话，不阐释；</li><li>关键词，要写全；</li><li>重点内容，要突出；</li><li>文字之间，要留白。</li></ul><p>做语音信息的视觉笔记时，时间是个非常重要的因素，我们一定要先以文字的形式把信息写下来，而不是先去画画。因为，画画会让你分心，无法专注于聆听，可能你一个视觉元素没有画完，演讲者都已经讲了很多内容了。</p><p>我们还是要以内容为王。等文字内容记下来以后，先给内容找个容器装起来就可以，时间允许的前提下再去补充视觉元素。</p><p>而且，笔记体现的文字信息最好就是对方讲话中的原话，而不是自己的诠释和理解。自己的阐释和理解不仅容易对原文内容的意思产生影响，还会影响你的记录速度，因为你的思考也是要花时间的。</p><p>同时，你还要把关键词写全（形成一个短语或一句话），如果你的视觉笔记是想分享出去给别人看的，就尤其需要注意这一点。如果你根据自己的理解，对关键词做了一些删减、更改，很容易让不了解内容的人看不懂。</p><p>记录文字内容的时候，还要特别注意要突出重要的内容，你可以把重点内容的文字写得明显一些、大一些。当然，也要兼顾文字信息之间的留白，把相关的内容记在距离较近的地方，更方便你在后期进行视觉元素的补充。</p><h3 id="_3-整理逻辑" tabindex="-1">3.整理逻辑 <a class="header-anchor" href="#_3-整理逻辑" aria-label="Permalink to &quot;3.整理逻辑&quot;">​</a></h3><p>所谓整理逻辑，说白了其实就是要把你记录的内容点模块化和逻辑化，让它们有个合适的构图呈现。最终目的是让自己和看到视觉笔记的人，能够看懂内容之间的逻辑。</p><p>动态信息的记录中 <strong>最简单的逻辑就是线性的时间关系</strong>，就是讲述者先讲了什么，后讲了什么。你的每一步记录，都是在处理后面讲的内容跟前面讲的内容之间的关系。还记得容器篇的内容吗？当时我们利用对话框来做动态信息的记录，只用人物和对话框再加上箭头串联就可以完成整个逻辑链。</p><p>由于动态信息的逻辑可能需要边听边去梳理，这也就更加凸显了留白的重要性。我们先把每个要点的信息捕捉下来，再去看每个点之间的逻辑关系是什么。</p><p>整理逻辑最好是在内容记得差不多的时候进行，这样你才不容易使“听”和“记”混乱起来。我们聆听的时候，其实是在了解对方的逻辑，梳理对方的逻辑；而记录的时候，我们是在用自己的逻辑试着去重现对方的逻辑。整理逻辑的这个过程是两个逻辑的集合。</p><h3 id="_4-视觉美化" tabindex="-1">4.视觉美化 <a class="header-anchor" href="#_4-视觉美化" aria-label="Permalink to &quot;4.视觉美化&quot;">​</a></h3><p>逻辑构图都整理好后，我们就可以进行视觉的美化了，这一步你可以趁休息时间或者是结束以后进行。</p><p>你需要在这一步中根据内容绘制一些“演员和道具”来诠释内容，让内容更加丰富。涂色也是在这个阶段完成的，具体的颜色搭配你可以去参考 <a href="https://time.geekbang.org/column/article/234249" target="_blank" rel="noreferrer">色彩篇</a> 的内容。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%A7%86%E8%A7%89%E7%AC%94%E8%AE%B0%E5%85%A5%E9%97%A8%E8%AF%BE/images/238311/91e4f498a6e69804876faa172d1d43e3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%A7%86%E8%A7%89%E7%AC%94%E8%AE%B0%E5%85%A5%E9%97%A8%E8%AF%BE/images/238311/91e4f498a6e69804876faa172d1d43e3.jpg" alt=""></a></p><p>最后，别忘记签上你的专有姓名和日期，表示作品完成。</p><p>虽然聆听内容、记录信息、整理逻辑、视觉美化这四个步骤看似很简单，但是真正操作还是有难度的，它需要你不断地进行练习。</p><p>我在文章中插入了我在做《 <a href="https://www.yixi.tv/zhiya/19/40" target="_blank" rel="noreferrer">我其实对新闻不是特别感兴趣</a>》视觉笔记时候的一个录屏视频，你可以感受下这几个步骤，因为我的绘画速度很快，所以很多时候我都是视觉图像和内容同步进行记录的，但是你可以慢慢来，不用着急。</p><h2 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h2><p>今天的作业是自己对一段演讲或者一次会议进行实时视觉笔记的记录。</p><p>如果你有任何疑问可以在留言区提问。同时，欢迎点击下面的“交作业”图片链接，去部落分享你的练习成果，期待看到你的作业。</p>',44)])])}const b=a(r,[["render",n]]);export{d as __pageData,b as default};
